from itertools import combinations

e = list(combinations(range(8), 2))

for coloring in range(2**28):
    color_list = [(coloring >> i) & 1 for i in range(28)]

    valid = True
    for c in range(2):
        for clique in combinations(range(8), 4):
            clique_edges = [(i, j) for i, j in combinations(clique, 2)]
            clique_colors = [color_list[e.index(edge)] for edge in clique_edges]
            if all(x == c for x in clique_colors):
                valid = False
                break
        if not valid:
            break

    if valid:
        print([int(i) for i in bin(coloring)[2:].zfill(28)])
        break
else:
    print("UNSATISFIABLE")
